def nth(n, seq):
    """Returns nth item in the sequence or None if no such item exists."""
    try:
        return seq[n]
    except IndexError:
        if n < 0:
            return seq[0]
        return None
    except TypeError:
        return next(islice(seq, n + 1, None), None)

